<?= $this->extend('layouts/management') ?><?= $this->section('content') ?><section class="surface"><div class="toolbar"><p>Kelompokkan produk agar mudah ditemukan pelanggan.</p><a class="btn btn-primary" href="<?= site_url('admin/categories/create') ?>">+ Tambah Kategori</a></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Nama</th><th>Slug</th><th>Deskripsi</th><th>Aksi</th></tr></thead><tbody><?php foreach($categories as $c): ?><tr><td><strong><?= esc($c['name']) ?></strong></td><td><?= esc($c['slug']) ?></td><td><?= esc($c['description']) ?></td><td class="actions"><a class="btn btn-sm btn-outline-primary" href="<?= site_url('admin/categories/edit/'.$c['id']) ?>">Edit</a><form method="post" action="<?= site_url('admin/categories/delete/'.$c['id']) ?>" onsubmit="return confirm('Hapus kategori ini?')"><?= csrf_field() ?><button class="btn btn-sm btn-outline-danger">Hapus</button></form></td></tr><?php endforeach ?><?php if(!$categories): ?><tr><td colspan="4">Belum ada kategori.</td></tr><?php endif ?></tbody></table></div></section><?= $this->endSection() ?>